-- SQLite-compatible logical schema. Operational CSV/JSON exports mirror these entities.
PRAGMA foreign_keys = ON;
CREATE TABLE Supplier (supplier_id TEXT PRIMARY KEY, supplier_name TEXT NOT NULL, country TEXT NOT NULL, risk_tier TEXT NOT NULL CHECK(risk_tier IN ('LOW','MEDIUM','HIGH')), status TEXT NOT NULL);
CREATE TABLE MaterialLot (material_lot_id TEXT PRIMARY KEY, supplier_id TEXT NOT NULL REFERENCES Supplier(supplier_id), material_id TEXT NOT NULL, received_date TEXT NOT NULL, quantity_received REAL NOT NULL CHECK(quantity_received >= 0), quantity_available REAL NOT NULL CHECK(quantity_available >= 0), unit TEXT NOT NULL, status TEXT NOT NULL);
CREATE TABLE Product (product_id TEXT PRIMARY KEY, product_name TEXT NOT NULL, category TEXT NOT NULL, unit TEXT NOT NULL);
CREATE TABLE BOM (bom_id TEXT NOT NULL, product_id TEXT NOT NULL REFERENCES Product(product_id), material_id TEXT NOT NULL, quantity_per_unit REAL NOT NULL CHECK(quantity_per_unit > 0), effective_from TEXT NOT NULL, effective_to TEXT, revision TEXT NOT NULL, PRIMARY KEY(bom_id, material_id));
CREATE TABLE ProductionOrder (production_order_id TEXT PRIMARY KEY, product_id TEXT NOT NULL REFERENCES Product(product_id), bom_id TEXT NOT NULL, planned_quantity REAL NOT NULL, actual_quantity REAL NOT NULL, planned_start TEXT NOT NULL, actual_start TEXT NOT NULL, actual_end TEXT NOT NULL, status TEXT NOT NULL);
CREATE TABLE MaterialConsumption (consumption_id TEXT PRIMARY KEY, production_order_id TEXT NOT NULL REFERENCES ProductionOrder(production_order_id), material_lot_id TEXT NOT NULL REFERENCES MaterialLot(material_lot_id), material_id TEXT NOT NULL, quantity_consumed REAL NOT NULL CHECK(quantity_consumed > 0), consumed_at TEXT NOT NULL);
CREATE TABLE FinishedLot (finished_lot_id TEXT PRIMARY KEY, production_order_id TEXT NOT NULL REFERENCES ProductionOrder(production_order_id), product_id TEXT NOT NULL REFERENCES Product(product_id), manufactured_date TEXT NOT NULL, quantity_produced REAL NOT NULL, quantity_available REAL NOT NULL, status TEXT NOT NULL);
CREATE TABLE Shipment (shipment_id TEXT PRIMARY KEY, carrier_name TEXT NOT NULL, warehouse_id TEXT NOT NULL, dispatch_date TEXT NOT NULL, status TEXT NOT NULL);
CREATE TABLE ShipmentLot (shipment_lot_id TEXT PRIMARY KEY, shipment_id TEXT NOT NULL REFERENCES Shipment(shipment_id), finished_lot_id TEXT NOT NULL REFERENCES FinishedLot(finished_lot_id), quantity_shipped REAL NOT NULL);
CREATE TABLE Customer (customer_id TEXT PRIMARY KEY, customer_name TEXT NOT NULL, customer_type TEXT NOT NULL, country TEXT NOT NULL);
CREATE TABLE Delivery (delivery_id TEXT PRIMARY KEY, shipment_id TEXT NOT NULL REFERENCES Shipment(shipment_id), finished_lot_id TEXT NOT NULL REFERENCES FinishedLot(finished_lot_id), customer_id TEXT NOT NULL REFERENCES Customer(customer_id), delivery_date TEXT NOT NULL, quantity_delivered REAL NOT NULL, status TEXT NOT NULL);
CREATE TABLE RecallCase (recall_case_id TEXT PRIMARY KEY, trigger_entity_type TEXT NOT NULL, trigger_lot_id TEXT NOT NULL, reason TEXT NOT NULL, severity TEXT NOT NULL, opened_at TEXT NOT NULL, status TEXT NOT NULL, scope_delivery_count INTEGER NOT NULL, scope_quantity REAL NOT NULL);
CREATE TABLE RecallAction (recall_action_id TEXT PRIMARY KEY, recall_case_id TEXT NOT NULL REFERENCES RecallCase(recall_case_id), action_type TEXT NOT NULL, target_type TEXT NOT NULL, target_id TEXT NOT NULL, action_date TEXT NOT NULL, status TEXT NOT NULL, quantity REAL NOT NULL, notes TEXT);
CREATE TABLE StateEvent (event_id TEXT PRIMARY KEY, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, from_state TEXT, to_state TEXT NOT NULL, event_time TEXT NOT NULL, reason TEXT NOT NULL);
